import {existsSync} from 'node:fs';
import test from 'node:test';
import assert from 'node:assert/strict';
import { readFile } from 'node:fs/promises';
import { inflateSync } from 'node:zlib';
import { detectScoreSystems, normalizeCropRect, planScoreImageChunks } from '../lib/score-image-layout.mjs';
import { prepareScoreImage } from '../src/score-image.js';

function page(width = 800, height = 1100) {
  return { width, height, data: new Uint8Array(width * height).fill(255) };
}

function ink(image, x, y, width, height, value = 0) {
  for (let row = Math.max(0, y); row < Math.min(image.height, y + height); row++) {
    for (let column = Math.max(0, x); column < Math.min(image.width, x + width); column++) {
      image.data[row * image.width + column] = value;
    }
  }
}

function staff(image, top, spacing = 8) {
  for (let index = 0; index < 5; index++) ink(image, 64, top + index * spacing, image.width - 128, 2);
  // Notes, stems, a bar line and ledger marks must not create extra staves.
  for (const [x, offset] of [[180, 12], [306, 28], [448, 4], [590, 36]]) {
    ink(image, x, top + offset, 11, 5);
    ink(image, x + 9, top + offset - 24, 2, 28);
  }
  ink(image, 400, top, 2, spacing * 4 + 2);
  ink(image, 584, top + 40, 23, 2);
}

function watermarkAndNoise(image) {
  // A light diagonal watermark crosses the real staff lines.
  for (let x = 0; x < image.width; x++) {
    const y = 120 + Math.floor(x * 0.55);
    for (let offset = 0; offset < 10; offset++) {
      const index = (y + offset) * image.width + x;
      if (index < image.data.length && image.data[index] > 185) image.data[index] = 185;
    }
  }
  let random = 173;
  for (let index = 0; index < 500; index++) {
    random = (random * 1664525 + 1013904223) >>> 0;
    const x = random % image.width;
    random = (random * 1664525 + 1013904223) >>> 0;
    const y = random % image.height;
    ink(image, x, y, 2, 2, 30);
  }
}

function pianoPage() {
  const image = page();
  // Header blocks resemble a title/composer but contain no five-line structure.
  ink(image, 270, 55, 260, 14);
  ink(image, 610, 100, 110, 7);
  for (const top of [200, 288, 540, 628]) staff(image, top);
  watermarkAndNoise(image);
  return image;
}

function assertInside(rect, width, height) {
  assert.ok(rect && ['x', 'y', 'width', 'height'].every(key => Number.isInteger(rect[key])));
  assert.ok(rect.x >= 0 && rect.y >= 0 && rect.width > 0 && rect.height > 0);
  assert.ok(rect.x + rect.width <= width && rect.y + rect.height <= height);
}

test('thin gray staff lines and variable hand spacing retain every complete piano system', () => {
  const image = page(1600, 2100);
  // Raster PDF pages can have pale lines while the note heads remain black.
  // Hand spacing varies within a page; the smallest gap is not a safe cutoff.
  for (const top of [266, 420, 618, 780, 980, 1148, 1346, 1532, 1729, 1917]) {
    staff(image, top, 14);
    for (let line = 0; line < 5; line++) ink(image, 64, top + line * 14, image.width - 128, 2, 195);
  }
  const layout = detectScoreSystems(image, { pianoSourceVerified: true });
  assert.equal(layout.staffs.length, 10);
  assert.equal(layout.systems.length, 5);
  assert.ok(layout.systems.every(system => system.staffs.length === 2));
  assert.equal(layout.assessment.canRequestOcr, true);
});

function connectedPianoPage(tops=[100,202,314,412,523,628,740,850,962,1050]) {
  const image=page(800,1200);
  for(const top of tops)staff(image,top);
  // The printed system-start bar joins the hands even when hand spacing is
  // almost the same as (or larger than) the gap to the following system.
  for(let i=0;i<tops.length;i+=2)ink(image,65,tops[i],2,tops[i+1]+34-tops[i]);
  return image;
}

test('printed connectors retain five grand staffs when variable hand and row gaps are nearly equal',()=>{
  const layout=detectScoreSystems(connectedPianoPage(),{pianoSourceVerified:true});
  assert.equal(layout.staffs.length,10);assert.equal(layout.systems.length,5);
  assert.ok(layout.systems.every(system=>system.staffs.length===2));
  for(let index=0;index<5;index++)assert.deepEqual(layout.systems[index].staffs,layout.staffs.slice(index*2,index*2+2));
});

test('connected hands may be farther apart than adjacent systems without pairing across systems',async()=>{
  const image=connectedPianoPage([100,250,330,480]);
  await withPreparedImage(image,{pianoSourceVerified:true},prepared=>{
    assert.equal(prepared.systems.length,2);
    for(const system of prepared.systems){
      assert.equal(system.staffs.length,2);
      const [chunk]=prepared.getSelection({selectedSystemIds:[system.id]});
      assert.equal(chunk.assessment.canRequestOcr,true);
      assert.ok(chunk.region.rect.y<=system.staffs[0].lines[0]);
      assert.ok(chunk.region.rect.y+chunk.region.rect.height>system.staffs[1].lines[4]);
    }
  });
});

// Exercise the actual browser preprocessing/selection seam without any model or network call.
async function withPreparedImage(fixture, options, run) {
  const previous = { Image: globalThis.Image, document: globalThis.document };
  class Canvas {
    constructor() { this.width = 0; this.height = 0; this.data = new Uint8Array(); }
    getContext() { return { fillStyle: '#fff', fillRect: () => { this.data = new Uint8Array(this.width * this.height).fill(255); },
      drawImage: (source, ...args) => {
        const input = source.fixture || source;
        let sx=0,sy=0,sw=input.width,sh=input.height,dx=0,dy=0,dw=this.width,dh=this.height;
        if(args.length===4)[dx,dy,dw,dh]=args;
        if(args.length===8)[sx,sy,sw,sh,dx,dy,dw,dh]=args;
        this.data=new Uint8Array(this.width*this.height).fill(255);
        for(let y=0;y<dh;y++)for(let x=0;x<dw;x++)this.data[(y+dy)*this.width+x+dx]=input.data[Math.min(input.height-1,Math.floor(sy+y*sh/dh))*input.width+Math.min(input.width-1,Math.floor(sx+x*sw/dw))];
      }, getImageData: () => ({width:this.width,height:this.height,data:this.data}) }; }
    toDataURL() { return 'data:image/png;base64,iVBORw0KGgoAAAANS'; }
  }
  globalThis.document = { createElement: name => { assert.equal(name,'canvas'); return new Canvas(); } };
  globalThis.Image = class { constructor(){this.fixture=fixture;this.naturalWidth=fixture.width;this.naturalHeight=fixture.height;} set src(_value){queueMicrotask(()=>this.onload());} };
  let prepared;
  try { prepared=await prepareScoreImage('actual-score-image.png',options); return await run(prepared); }
  finally { prepared?.destroy(); globalThis.Image=previous.Image;globalThis.document=previous.document; }
}

test('real piano photograph, book cover and guitar TAB cannot become Pi OCR inputs by filename or user confirmation', async () => {
  for(const fixture of realNegativeFixtures){
    const image={...fixture,data:new Uint8Array(inflateSync(Buffer.from(fixture.grayZlib,'base64')))};
    await withPreparedImage(image,{pianoSourceVerified:true,sourceLabel:'mislabelled-piano.jpg'},prepared=>{
      assert.throws(()=>prepared.getSelection({mode:'page',confirmedPiano:true}),/谱面|五线|双手|六线/,fixture.name);
    });
  }
});

test('gray resampling bands do not erase a hand during page and crop validation', async () => {
  const image=page(800,500);
  staff(image,100);staff(image,230);
  ink(image,65,100,2,164);
  // Pale interpolation ink joins two bass lines only at the default threshold.
  ink(image,64,232,672,7,205);
  const fixed=detectScoreSystems(image,{lineThreshold:210,pianoSourceVerified:true});
  assert.equal(fixed.assessment.reasonCode,'GRAND_STAFF_UNCONFIRMED');
  await withPreparedImage(image,{pianoSourceVerified:true},prepared=>{
    assert.equal(prepared.systems.length,1);
    assert.equal(prepared.systems[0].staffs.length,2);
    assert.equal(prepared.getAssessment().canRequestOcr,true);
    assert.equal(prepared.getSelection()[0].assessment.hasGrandStaff,true);
    // A complete page must not authorize a manually cropped single hand.
    assert.equal(prepared.getAssessment({mode:'manual',rect:{x:0,y:70,width:800,height:90}}).canRequestOcr,false);
  });
});

test('six parallel guitar TAB lines cannot be silently reduced to a five-line piano staff', async () => {
  const image=page(800,500);
  for(const top of[110,220])for(let i=0;i<6;i++)ink(image,64,top+i*8,672,2);
  for(const top of[110,220])for(const x of[180,310,450])ink(image,x,top+14,9,11);
  await withPreparedImage(image,{pianoSourceVerified:true},prepared=>assert.throws(()=>prepared.getSelection({mode:'page',confirmedPiano:true}),/谱面|五线|双手|六线/));
});

test('geometric grand staff is a piano candidate until a source or the user confirms its instrument', async () => {
  await withPreparedImage(pianoPage(),{},prepared=>{
    assert.throws(()=>prepared.getSelection(),/确认|核对/);
    assert.equal(prepared.assessment.pianoVerified,false);
    const chunks=prepared.getSelection({confirmedPiano:true});
    assert.equal(chunks.length,1);assert.equal(chunks[0].assessment.verification,'user');
  });
});

async function originalScorePixels(filename='network-original-sheet.png') {
  // Decode the existing 8-bit indexed/RGB PNG fixtures without adding a production dependency.
  const png=await readFile(new URL(`../evidence/${filename}`,import.meta.url));
  const width=png.readUInt32BE(16),height=png.readUInt32BE(20),type=png[25],channels=type===2?3:type===6?4:1;assert.equal(png[24],8);assert.ok([0,2,3,6].includes(type));
  let palette;const parts=[];
  for(let offset=8;offset<png.length;){const length=png.readUInt32BE(offset),kind=png.toString('ascii',offset+4,offset+8),body=png.subarray(offset+8,offset+8+length);if(kind==='PLTE')palette=body;if(kind==='IDAT')parts.push(body);offset+=length+12;}
  const rowBytes=width*channels,filtered=inflateSync(Buffer.concat(parts)),indices=new Uint8Array(rowBytes*height);
  const paeth=(a,b,c)=>{const p=a+b-c,pa=Math.abs(p-a),pb=Math.abs(p-b),pc=Math.abs(p-c);return pa<=pb&&pa<=pc?a:pb<=pc?b:c;};
  for(let y=0;y<height;y++){const filter=filtered[y*(rowBytes+1)];for(let x=0;x<rowBytes;x++){const index=y*rowBytes+x,a=x>=channels?indices[index-channels]:0,b=y?indices[index-rowBytes]:0,c=x>=channels&&y?indices[index-rowBytes-channels]:0;const predictor=filter===0?0:filter===1?a:filter===2?b:filter===3?Math.floor((a+b)/2):paeth(a,b,c);indices[index]=(filtered[y*(rowBytes+1)+x+1]+predictor)&255;}}
  const data=new Uint8Array(width*height);for(let i=0;i<data.length;i++){if(type===0){data[i]=indices[i];continue;}const j=type===3?indices[i]*3:i*channels,color=type===3?palette:indices,alpha=type===6?indices[j+3]/255:1;data[i]=Math.round((color[j]*.299+color[j+1]*.587+color[j+2]*.114)*alpha+255*(1-alpha));}
  return{width,height,data};
}

test('actual full-size grand staff keeps five systems and source verification still requires musical geometry',{skip:!existsSync(new URL('../evidence/network-original-sheet.png',import.meta.url))&&'optional private image fixture is not present'},async()=>{
  const image=await originalScorePixels();
  await withPreparedImage(image,{pianoSourceVerified:true,sourceLabel:'Verified Piano Solo catalogue'},prepared=>{
    assert.equal(prepared.systems.length,5);assert.equal(prepared.assessment.hasGrandStaff,true);
    assert.equal(prepared.assessment.verification,'source');assert.equal(prepared.assessment.canAutoRecognize,true);
    const chunks=prepared.getSelection();assert.equal(chunks.length,1);assert.equal(chunks[0].assessment.verification,'source');
    assert.throws(()=>prepared.getSelection({mode:'manual',rect:{x:0,y:0,width:1000,height:250},confirmedPiano:true}),/五线|谱面|双手/);
  });
  const ruled=page();for(const y of[200,288])for(let i=0;i<5;i++)ink(ruled,64,y+i*8,672,2);
  await withPreparedImage(ruled,{pianoSourceVerified:true},prepared=>assert.throws(()=>prepared.getSelection({mode:'page',confirmedPiano:true}),/五线|谱面|双手/));
});

test('actual dense piano solo first system preserves both staffs when the left hand has full-bar rests',{skip:!existsSync(new URL('../evidence/international-imslp-yeung-page1.png',import.meta.url))&&'optional private image fixture is not present'},async()=>{
  const image=await originalScorePixels('international-imslp-yeung-page1.png');
  await withPreparedImage(image,{pianoSourceVerified:true,sourceLabel:'Verified For Piano Solo heading'},prepared=>{
    assert.equal(prepared.systems.length,4);assert.ok(prepared.systems.every(system=>system.staffs.length===2));
    assert.equal(prepared.getAssessment().canRequestOcr,true);
    assert.equal(prepared.getSelection()[0].assessment.verification,'source');
    assert.equal(prepared.getAssessment({mode:'manual',rect:null}).canRequestOcr,false);
    assert.equal(prepared.getAssessment({selectedSystemIds:[]}).canRequestOcr,false);
  });
});

test('two grand-staff systems survive note/stem noise and a grey watermark', () => {
  const image = pianoPage();
  const layout = detectScoreSystems(image);
  assert.equal(layout.width, image.width);
  assert.equal(layout.height, image.height);
  assert.equal(layout.staffs.length, 4);
  assert.equal(layout.systems.length, 2);
  assert.deepEqual(layout.systems.map(system => system.staffs.length), [2, 2]);
  const tops = layout.staffs.map(item => item.lines[0]).sort((a, b) => a - b);
  [200, 288, 540, 628].forEach((expected, index) => assert.ok(Math.abs(tops[index] - expected) <= 2));
  for (const system of layout.systems) {
    assertInside(system.rect, image.width, image.height);
    assert.ok(typeof system.id === 'string' && system.id.length > 0);
    assert.ok(Number.isFinite(system.confidence) && system.confidence >= 0 && system.confidence <= 1);
    for (const detectedStaff of system.staffs) {
      assert.equal(detectedStaff.lines.length, 5);
      assert.ok(Math.abs(detectedStaff.spacing - 8) <= 1);
      assert.ok(detectedStaff.lines[0] >= system.rect.y);
      assert.ok(detectedStaff.lines.at(-1) < system.rect.y + system.rect.height);
    }
  }
  assert.ok(layout.systems[0].rect.y < layout.systems[1].rect.y);
});

test('RGBA and greyscale inputs describe the same printed staff geometry', () => {
  const image = pianoPage();
  const rgba = new Uint8ClampedArray(image.data.length * 4);
  for (let index = 0; index < image.data.length; index++) {
    rgba[index * 4] = rgba[index * 4 + 1] = rgba[index * 4 + 2] = image.data[index];
    rgba[index * 4 + 3] = 255;
  }
  const mono = detectScoreSystems(image);
  const color = detectScoreSystems({ ...image, data: rgba });
  assert.equal(color.systems.length, mono.systems.length);
  assert.deepEqual(color.staffs.map(item => item.lines), mono.staffs.map(item => item.lines));
  // Transparent PNG whitespace is visually white, even when its hidden RGB is 0.
  for (let index = 0; index < image.data.length; index++) if (image.data[index] === 255) {
    rgba[index * 4] = rgba[index * 4 + 1] = rgba[index * 4 + 2] = rgba[index * 4 + 3] = 0;
  }
  const transparent = detectScoreSystems({ ...image, data: rgba });
  assert.deepEqual(transparent.staffs.map(item => item.lines), mono.staffs.map(item => item.lines));
});

test('widely separated single staves remain two systems rather than a fictitious piano pair', () => {
  const image = page(800, 850);
  staff(image, 170);
  staff(image, 510);
  const layout = detectScoreSystems(image);
  assert.equal(layout.staffs.length, 2);
  assert.equal(layout.systems.length, 2);
  assert.deepEqual(layout.systems.map(system => system.staffs.length), [1, 1]);
});

test('blank pages and four unrelated horizontal rules do not produce a false five-line staff', () => {
  const blank = page(600, 500);
  const layout = detectScoreSystems(blank);
  assert.equal(layout.systems.length, 0);
  assert.equal(layout.staffs.length, 0);
  assert.ok(layout.warnings.length > 0);
  const chunks = planScoreImageChunks(layout);
  assert.equal(chunks.length, 1);
  assert.deepEqual(chunks[0].rect, { x: 0, y: 0, width: 600, height: 500 });
  assert.deepEqual(chunks[0].systemIndices, []);
  assert.ok(Array.isArray(chunks[0].warnings) && chunks[0].warnings.length > 0);
  assert.deepEqual(planScoreImageChunks(layout, { selectedSystemIds: [] }), []);
  for (let index = 0; index < 4; index++) ink(blank, 40, 150 + index * 9, 520, 2);
  assert.equal(detectScoreSystems(blank).staffs.length, 0);
});

test('chunk plans preserve reading order, page bounds and an explicit system selection', () => {
  const layout = detectScoreSystems(pianoPage());
  const all = planScoreImageChunks(layout);
  assert.equal(all.length, 2);
  all.forEach((chunk, index) => {
    assertInside(chunk.rect, layout.width, layout.height);
    assert.equal(chunk.page, 1);
    assert.deepEqual(chunk.systemIndices, [layout.systems[index].index]);
    assert.deepEqual(chunk.contextRect, layout.contextRect);
    assert.ok(Array.isArray(chunk.warnings));
  });
  const chosen = layout.systems[1];
  const selected = planScoreImageChunks(layout, { selectedSystemIds: [chosen.id] });
  assert.equal(selected.length, 1);
  assert.deepEqual(selected[0].systemIndices, [chosen.index]);
  assert.deepEqual(planScoreImageChunks(layout, { selectedSystemIds: [] }), []);
  assert.deepEqual(planScoreImageChunks(layout, { selectedSystemIds: ['missing-id'] }), []);
});

test('crop normalization clips the original intersection and rejects an empty or invalid region', () => {
  const input = Object.freeze({ x: -12, y: 30, width: 100, height: 50 });
  assert.deepEqual(normalizeCropRect(input, 800, 1100), { x: 0, y: 30, width: 88, height: 50 });
  assert.deepEqual(normalizeCropRect({ x: 790, y: 1090, width: 40, height: 20 }, 800, 1100),
    { x: 790, y: 1090, width: 10, height: 10 });
  assertInside(normalizeCropRect({ x: 1.25, y: 2.75, width: 22.5, height: 31.5 }, 800, 1100), 800, 1100);
  for (const rect of [null, { x: NaN, y: 0, width: 10, height: 10 },
    { x: 900, y: 0, width: 10, height: 10 }, { x: 0, y: 0, width: 0, height: 10 },
    { x: 0, y: 0, width: 10, height: -5 }]) {
    assert.throws(() => normalizeCropRect(rect, 800, 1100));
  }
});

